import{z as A,x as p,o as t,c as B,q as s,j as E,D as r,d as n,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"SSA 构造 Cytron","description":"","frontmatter":{"title":"SSA 构造 Cytron","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssa-construction-cytron.md","filePath":"cs/ssa-construction-cytron.md","lastUpdated":1791063341000}'),d={name:"cs/ssa-construction-cytron.md"};function S(D,a,m,u,C,c){const o=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=s('<h1 id="ssa-构造-cytron" tabindex="-1">SSA 构造 Cytron <a class="header-anchor" href="#ssa-构造-cytron" aria-label="Permalink to &quot;SSA 构造 Cytron&quot;">​</a></h1><div class="epigraph"><p>在支配边界插入 φ，再按支配树重命名，得到静态单赋值。Cytron 等人给出与支配树相关的高效放置。</p><footer>—— 据 Cytron et al., Efficiently Computing Static Single Assignment Form, 1991；Lengauer and Tarjan 支配；Appel, SSA is Functional Programming 整理</footer></div><p>上一课<a href="/cs/value-range-analysis">值范围</a>已在 SSA 上说话。主干<a href="/cs/ssa-form">SSA</a>给直觉。缺口是<strong>构造算法</strong>：支配树、支配边界、φ 迭代插入、重命名栈。本课钉 Cytron 步骤，不写析构——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素在每个汇合点对每个变量插 φ 太多。只需：变量在块定值，则在其支配边界插 φ，再迭代。缺口是<strong>支配边界 DF</strong>，不是值编号。</p><p><span class="marginnote">支配边界 DF 翻译成大白话：从你统治的块「绕出去」第一站遇到的那些块——变量在这条路能流到、但你的块管不住它的位置。汇合正是发生在这种「绕出去」的地方，所以 φ 恰好只需要插在 DF 上：这是「插得准」的根据，也是 Cytron 算法比朴素全插少一大截的原因。</span></p><p>Lengauer–Tarjan 算支配。剪枝 SSA：无 use 的名不插 φ。semi-pruned 用 liveness 粗筛。</p><h3 id="φ-的操作数对应前驱边" tabindex="-1">φ 的操作数对应前驱边 <a class="header-anchor" href="#φ-的操作数对应前驱边" aria-label="Permalink to &quot;φ 的操作数对应前驱边&quot;">​</a></h3><p>顺序与 CFG 前驱列表对齐。错位则语义错。这不是「任意交换」。</p><p><span class="marginnote">Cytron et al. 1991 TOPLAS。Appel 1998。主干 SSA 课已禁止把 φ 当机器指令。本课补算法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ol><li>算支配树与 DF。2. 对每个变量的定值块工作表插 φ。3. 支配树 DFS，栈重命名，φ 操作数填入到达名。</li></ol>',12)),(t(),E(i,null,{default:r(()=>[l(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20DOM%5B%22%E6%94%AF%E9%85%8D%E6%A0%91%22%5D%0A%20%20DOM%20--%3E%20DF%5B%22%E6%94%AF%E9%85%8D%E8%BE%B9%E7%95%8C%22%5D%0A%20%20DF%20--%3E%20PHI%5B%22%E6%8F%92%20%CF%86%22%5D%0A%20%20PHI%20--%3E%20RN%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 mem2reg：alloca 的 store/load 先当定值/使用再走同一算法——接 SROA。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"初学者最容易在这里犯的错：把 φ 当成一条会在运行时执行的机器指令。实际上 φ 是编译器内部的「多选一」记号——控制流从哪条前驱边进来，φ 的值就取哪条边对应的操作数；析构阶段它会被翻译成普通拷贝。这也是为什么 φ 的操作数顺序必须和 CFG 前驱列表严格对齐，错一位整个语义就换了。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"不可约 CFG 仍可 SSA，φ 更多。关键边有时先拆，方便后边析构。不要在构造时做 GVN；顺序是先 SSA 再优化。",-1)),a[7]||(a[7]=e("p",null,"复杂度：近线性支配 + 与定值数相关的 φ 插入。",-1)),(t(),E(i,null,{default:r(()=>[l(o,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENTER%5B%22%E8%BF%9B%E5%85%A5%E5%9D%97%20B%22%5D%20--%3E%20PUSH%5B%22%E6%AF%8F%E4%B8%AA%E5%9C%A8%20B%20%E5%AE%9A%E5%80%BC%E7%9A%84%E5%8F%98%E9%87%8F%E5%8E%8B%E5%85%A5%E6%96%B0%E5%90%8D%22%5D%0A%20%20PUSH%20--%3E%20REW%5B%22B%20%E5%86%85%E5%AE%9A%E5%80%BC%E4%B8%8E%E4%BD%BF%E7%94%A8%E6%94%B9%E5%86%99%E4%B8%BA%E6%A0%88%E9%A1%B6%E5%90%8D%22%5D%0A%20%20REW%20--%3E%20SUCC%5B%22%E5%AF%B9%E6%AF%8F%E4%B8%AA%E5%90%8E%E7%BB%A7%EF%BC%9A%E5%BE%80%E5%85%B6%20%CF%86%20%E7%9A%84%E5%AF%B9%E5%BA%94%E5%89%8D%E9%A9%B1%E6%A7%BD%E5%A1%AB%E6%A0%88%E9%A1%B6%E5%90%8D%22%5D%0A%20%20SUCC%20--%3E%20KIDS%5B%22%E9%80%92%E5%BD%92%E5%A4%84%E7%90%86%E6%94%AF%E9%85%8D%E6%A0%91%E7%9A%84%E5%AD%90%E5%9D%97%22%5D%0A%20%20KIDS%20--%3E%20POP%5B%22%E7%A6%BB%E5%BC%80%20B%EF%BC%9A%E5%BC%B9%E6%8E%89%E6%9C%AC%E5%9D%97%E5%8E%8B%E5%85%A5%E7%9A%84%E5%90%8D%E5%AD%97%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">重命名栈的直觉类比：像编辑器的撤销栈——进入一个块就给用到的变量各「存档」一次，块内所有出现都读栈顶；离开块时把这一层的存档弹掉，外面看到的还是进块前的名字。支配序遍历保证「活着的影响范围」恰好等于「弹掉之前走过的子树」，所以栈不会乱。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 memory SSA 的全部 chi/mu。后课默认：标量可按 Cytron 构造 SSA。下一课析构：离开 SSA，φ 变传送。</p><p>也不把 SSA 当源语言语法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Cytron：DF 上插 φ，支配序重命名。</li><li>剪枝减少无用 φ。</li><li>支配算法用 Lengauer–Tarjan 等。</li><li>出处：Cytron et al., 1991；Lengauer–Tarjan；Appel, 1998。</li></ul>',6))])}const f=A(d,[["render",S]]);export{h as __pageData,f as default};
